import React, { useContext } from 'react';
import { TripContext } from '../context/TripContext';

const TripSummary = () => {
  const { families, expenses } = useContext(TripContext);

  const totalPeople = families.reduce((sum, fam) => sum + fam.members.length + 1, 0);
  const totalExpense = expenses.reduce((sum, exp) => sum + exp.amount, 0);
  const perPersonCost = totalPeople ? totalExpense / totalPeople : 0;

  // Calculate each family head's balance
  const summary = families.map(family => {
    const memberCount = family.members.length + 1;
    const share = memberCount * perPersonCost;
    const paid = expenses
      .filter(exp => exp.paidBy === family.head)
      .reduce((sum, exp) => sum + exp.amount, 0);
    return {
      family: family.head,
      paid,
      share,
      balance: parseFloat((paid - share).toFixed(2)),
    };
  });

  // Split into givers (owe money) and receivers (to get money)
  const givers = summary.filter(s => s.balance < 0).map(s => ({ ...s, balance: -s.balance }));
  const receivers = summary.filter(s => s.balance > 0).map(s => ({ ...s }));

  // Determine settlements
  const settlements = [];
  let i = 0, j = 0;

  while (i < givers.length && j < receivers.length) {
    const giver = givers[i];
    const receiver = receivers[j];
    const amount = Math.min(giver.balance, receiver.balance);

    settlements.push({
      from: giver.family,
      to: receiver.family,
      amount: amount.toFixed(2),
    });

    giver.balance -= amount;
    receiver.balance -= amount;

    if (giver.balance < 0.01) i++;
    if (receiver.balance < 0.01) j++;
  }

  return (
    <div style={{ marginTop: '30px', border: '1px solid #ccc', padding: '15px', borderRadius: '8px' }}>
      <h3>Trip Summary</h3>
      <p><strong>Total Expense:</strong> ₹{totalExpense.toFixed(2)}</p>
      <p><strong>Per Person Share:</strong> ₹{perPersonCost.toFixed(2)}</p>
      <h4>Each Family Summary</h4>
      <ul>
        {summary.map((item, index) => (
          <li key={index}>
            <strong>{item.family}</strong> paid ₹{item.paid.toFixed(2)}, share ₹{item.share.toFixed(2)} ⇒
            {item.balance >= 0
              ? ` gets ₹${item.balance.toFixed(2)}`
              : ` owes ₹${(-item.balance).toFixed(2)}`}
          </li>
        ))}
      </ul>

      <h4>Settlements</h4>
      {settlements.length === 0 ? (
        <p>All expenses are already settled.</p>
      ) : (
        <ul>
          {settlements.map((s, index) => (
            <li key={index}>
              <strong>{s.from}</strong> should pay ₹{s.amount} to <strong>{s.to}</strong>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default TripSummary;
